class Solution {
    public int longestStreak(int[] days) {
        int best = 0;
        for (int d : days) {
            int length = 1;
            while (contains(days, (long) d + length)) length++;
            best = Math.max(best, length);
        }
        return best;
    }

    private boolean contains(int[] days, long x) {
        for (int d : days) if (d == x) return true;
        return false;
    }
}

