int longestStreak(int* days, int daysSize) {
    int best = 0;
    for (int i = 0; i < daysSize; i++) {
        int length = 1;
        while (contains(days, daysSize, (long long) days[i] + length)) length++;
        if (length > best) best = length;
    }
    return best;
}

