        int[] s = days.clone();
        Arrays.sort(s);
        int current = 1, best = 1;
        for (int i = 1; i < s.length; i++) {
            if (s[i] == s[i - 1]) continue;
            current = (s[i] == s[i - 1] + 1) ? current + 1 : 1;
            best = Math.max(best, current);
        }
        return best;
    }
}

