static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int longestStreak(int* days, int daysSize) {
    if (daysSize == 0) return 0;
    int* s = malloc(daysSize * sizeof(int));
    memcpy(s, days, daysSize * sizeof(int));
    qsort(s, daysSize, sizeof(int), cmpInt);
    int current = 1, best = 1;
    for (int i = 1; i < daysSize; i++) {
        if (s[i] == s[i - 1]) continue;
        current = (s[i] == s[i - 1] + 1) ? current + 1 : 1;
        if (current > best) best = current;
    }
    free(s);
    return best;
}

