class Solution {
    public int longestStreak(int[] days) {
        Set<Long> have = new HashSet<>();
        for (int d : days) have.add((long) d);
        int best = 0;
        for (long d : have) {
            if (have.contains(d - 1)) continue;
            long end = d;
            while (have.contains(end + 1)) end++;
            best = Math.max(best, (int) (end - d + 1));
        }
        return best;
    }
}

